Method.Implementation:
 try{
		 do ##super()
		$$$TRACE("Connect to " _ ..ApplicationAddress)
		$$$TRACE("Connect to " _ ..TuxedoService)
		set ..objCdrTuxService = ##class(org.ihc.itf.cdr.drc.CdrDrcLastRunReportDate).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService, ..LogDirectory _"/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName))
     	set status = ..CheckObject()
	}catch err{
		$$$LOGERROR("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	    Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName," Exception while initializing Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)
	}	
	quit status

 #dim status as %Status	 
 set status = $$$OK
 $$$TRACE("Inside OnMessage method<" _ pRequest.StringValue _ ">")

 set tableObj = ##class(IHC.ITF.Response.MmiEventsTable).%New()
 set tableObj.ListOfMmiEventsRows = ##class(%ListOfObjects).%New()
 set tableObj.DataExists = 0

 $$$TRACE("objCdrTuxService Object valid: "_$IsObject(..objCdrTuxService))

 try {
      if (..CheckObject() '= $$$OK) {
	 	$$$TRACE("**** Object does not exists ****")
	 	// Try to re intialize
	 	set result = ..OnInit()
		if (result '= $$$OK){
			set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-Cdr-Dsql-GETREPORTDATE", "OpCdrGetReportDate failed. MMI#: " _pRequest.StringValue_ " ; Reason: " _ result)						
			return status
		}
 	}

	$$$TRACE("Object name: " _ ..objCdrTuxService.%ClassName(1))

	set output = ..objCdrTuxService.GetLastReportDate(..DrcUser)

	$$$TRACE("Output after invocation of GetLastReportDate Java Method<" _ output _ ">")

    set pResponse = ##class(IHC.ITF.Response.OpCdrGetReportDate).%New()
    set pResponse.reportDate = output

    $$$TRACE("Report Date (Response): <" _ output _ ">")
} catch err {		 	
       Set status = ..ExceptionHandler(err, "OnMessage")
 }

 $$$TRACE("OnMessage(GetLastReportDate) status: " _ status)	

 return status
